/* All model statistics are generated by export_web_data.py, not approximated in JS. */
'use strict';
const DATA = window.STARTUP_DATA;
const labels = ['研發支出', '行政支出', '行銷支出', 'Florida', 'New York'];
const maxima = [200000, 200000, 500000];
const example = [10000, 120000, 150000];
const $ = id => document.getElementById(id);
const format = (value, digits = 2) => new Intl.NumberFormat('en-US', {minimumFractionDigits: digits, maximumFractionDigits: digits}).format(value);
let selected = [0, 1, 2];
let spending = [...example];
let toastTimer;
const currentKey = () => selected.join('-');
const current = () => DATA.models[currentKey()];
function toast(message) { $('toast').textContent = message; $('toast').hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => $('toast').hidden = true, 2800); }
function download(name, content, type) { const url = URL.createObjectURL(new Blob([content], {type})); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }

function initControls() {
  $('feature-options').innerHTML = DATA.features.map((name, i) => `<label class="feature-option" id="feature-label-${i}"><input type="checkbox" value="${i}" ${selected.includes(i) ? 'checked' : ''}><span><strong>${labels[i]}</strong><small>${name}</small></span><span class="type">${i < 3 ? '數值' : '類別'}</span></label>`).join('');
  $('feature-options').addEventListener('change', event => {
    const input = event.target;
    if (!input.matches('input')) return;
    const next = [...$('feature-options').querySelectorAll('input:checked')].map(el => Number(el.value));
    if (!next.length) { input.checked = true; toast('請至少保留一個特徵。'); return; }
    selected = next; render();
  });
  $('spending-inputs').innerHTML = example.map((value, i) => `<div class="spending-group" id="spending-${i}"><div class="spending-title"><label for="amount-${i}">${labels[i]}</label><input type="number" id="amount-${i}" min="0" max="${maxima[i]}" step="100" value="${value}"></div><input type="range" id="range-${i}" aria-label="${labels[i]}滑桿" min="0" max="${maxima[i]}" step="100" value="${value}"><div class="range-label"><span>0</span><span>${format(maxima[i], 0)}</span></div></div>`).join('');
  example.forEach((_, i) => {
    $(`range-${i}`).addEventListener('input', e => { spending[i] = Number(e.target.value); $(`amount-${i}`).value = spending[i]; predict(); });
    $(`amount-${i}`).addEventListener('input', e => { if (e.target.value === '' || !e.target.validity.valid) { $('profit').textContent = '請檢查輸入'; $('prediction-range').textContent = ''; return; } spending[i] = Number(e.target.value); $(`range-${i}`).value = spending[i]; predict(); });
    $(`amount-${i}`).addEventListener('change', e => { let value = Number(e.target.value); if (!Number.isFinite(value)) value = example[i]; spending[i] = Math.min(maxima[i], Math.max(0, value)); e.target.value = spending[i]; $(`range-${i}`).value = spending[i]; predict(); });
  });
  $('state').addEventListener('change', predict);
  $('preset').addEventListener('change', e => { if (e.target.value !== 'custom') { selected = e.target.value.split('-').map(Number); render(); } });
  $('reset-inputs').addEventListener('click', () => { spending = [...example]; example.forEach((v, i) => { $(`amount-${i}`).value = v; $(`range-${i}`).value = v; }); $('state').value = 'California'; predict(); });
}

function prediction() {
  const model = current();
  const raw = [...spending, Number($('state').value === 'Florida'), Number($('state').value === 'New York')];
  const x = [1, ...selected.map(i => raw[i])];
  const d = model.deployment;
  const mean = x.reduce((sum, v, i) => sum + v * d.coefficients[i], 0);
  const variance = x.reduce((sum, v, i) => sum + x.reduce((s, w, j) => s + v * w * d.covariance[i][j], 0), 0);
  const delta = d.t95 * Math.sqrt(Math.max(0, variance + d.variance));
  return {input: Object.fromEntries(DATA.features.map((name, i) => [name, raw[i]])), profit: mean, prediction_interval_95: [mean-delta, mean+delta]};
}
function predict() {
  if (example.some((_, i) => $(`amount-${i}`).value === '' || !$(`amount-${i}`).validity.valid)) { $('profit').textContent = '請檢查輸入'; $('prediction-range').textContent = ''; return; }
  const result = prediction();
  $('profit').textContent = format(result.profit);
  $('prediction-range').textContent = `95% 預測區間 ${format(result.prediction_interval_95[0], 0)} – ${format(result.prediction_interval_95[1], 0)}`;
  example.forEach((_, i) => $(`spending-${i}`).classList.toggle('inactive-input', !selected.includes(i)));
  $('state').disabled = !selected.includes(3) && !selected.includes(4);
  const outside = selected.filter(i => i < 3).some(i => { const values = DATA.rows.map(r => r[DATA.features[i]]); return spending[i] < Math.min(...values) || spending[i] > Math.max(...values); });
  $('extrapolation').textContent = outside ? '此情境超出部分特徵的觀測範圍，屬於外推預測。' : '';
}

function scatterPlot(target, residual = false) {
  const model = current();
  const points = model.predictions.map(p => ({...p, x: residual ? p.predicted : p.actual, y: residual ? p.actual-p.predicted : p.predicted}));
  let lo = Math.min(...points.flatMap(p => residual ? [p.x] : [p.x, p.y]));
  let hi = Math.max(...points.flatMap(p => residual ? [p.x] : [p.x, p.y]));
  const pad = (hi-lo)*.12 || 1; lo -= pad; hi += pad;
  const maxResidual = Math.max(...points.map(p => Math.abs(p.y)), 1)*1.2;
  const ylo = residual ? -maxResidual : lo, yhi = residual ? maxResidual : hi;
  const x = v => 52+(v-lo)/(hi-lo)*270, y = v => 222-(v-ylo)/(yhi-ylo)*182;
  let svg = `<svg viewBox="0 0 350 268" role="img" aria-label="${residual ? '測試集殘差散布圖' : '測試集實際與預測利潤散布圖'}">`;
  for (let i=0; i<=4; i++) { const vx = lo+(hi-lo)*i/4, vy = ylo+(yhi-ylo)*i/4; svg += `<line class="gridline" x1="52" x2="322" y1="${y(vy)}" y2="${y(vy)}"/><text x="44" y="${y(vy)+3}" text-anchor="end">${(vy/1000).toFixed(0)}k</text><text x="${x(vx)}" y="241" text-anchor="middle">${(vx/1000).toFixed(0)}k</text>`; }
  svg += residual ? `<line class="reference" x1="52" x2="322" y1="${y(0)}" y2="${y(0)}"/>` : `<line class="reference" x1="${x(lo)}" y1="${y(lo)}" x2="${x(hi)}" y2="${y(hi)}"/>`;
  points.forEach(p => svg += `<circle class="point" cx="${x(p.x)}" cy="${y(p.y)}" r="4.5"><title>第 ${p.id} 筆｜實際 ${format(p.actual)}｜預測 ${format(p.predicted)}｜殘差 ${format(p.actual-p.predicted)}</title></circle>`);
  svg += `<text x="187" y="263" text-anchor="middle">${residual ? '預測利潤' : '實際利潤'}</text><text transform="translate(13 131) rotate(-90)" text-anchor="middle">${residual ? '殘差' : '預測利潤'}</text></svg>`;
  $(target).innerHTML = svg;
}

const subsetBest = Array.from({length:5}, (_, i) => Object.entries(DATA.models).filter(([, m]) => m.indices.length === i+1).sort((a,b) => a[1].cv_rmse-b[1].cv_rmse)[0]);
function renderComparison() {
  $('subset-table').innerHTML = subsetBest.map(([key, m]) => `<tr class="${key === currentKey() ? 'selected-row' : ''}"><td>${m.indices.length} 個</td><td>${m.indices.map(i => labels[i]).join('、')}</td><td>${format(m.cv_rmse)}</td><td><button class="chart-button" data-model="${key}" aria-label="載入 ${m.indices.length} 個特徵的模型">${key === currentKey() ? '使用中' : '載入'}</button></td></tr>`).join('');
  const values = subsetBest.map(([, m]) => m.cv_rmse), lo = Math.min(...values)*.98, hi = Math.max(...values)*1.02;
  const x = i => 80+i*109, y = v => 195-(v-lo)/(hi-lo)*155;
  let svg = '<svg viewBox="0 0 600 250" role="img" aria-label="不同特徵數的最低交叉驗證 RMSE">';
  for(let i=0;i<=3;i++){const v=lo+(hi-lo)*i/3;svg+=`<line class="gridline" x1="65" x2="545" y1="${y(v)}" y2="${y(v)}"/><text x="56" y="${y(v)+3}" text-anchor="end">${format(v,0)}</text>`;}
  svg += `<polyline class="line" points="${values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>`;
  values.forEach((v,i)=>{svg+=`<circle class="point" cx="${x(i)}" cy="${y(v)}" r="5"><title>${i+1} 個特徵：CV RMSE ${format(v)}</title></circle><text x="${x(i)}" y="220" text-anchor="middle">${i+1} 個特徵</text>`;});
  $('comparison-chart').innerHTML = svg+'<text x="20" y="20">CV RMSE ↓</text></svg>';
  $('method-table').innerHTML = DATA.methods.map(m=>`<tr><td>${m.method}</td><td>${m.n_features}</td><td>${format(m.cv_RMSE_mean)}</td><td>± ${format(m.cv_RMSE_std)}</td></tr>`).join('');
}
function renderData() {
  const rows = DATA.rows.filter(r => $('data-filter').value === 'all' || r.State === $('data-filter').value);
  $('row-count').textContent = `${rows.length} / 50 筆`;
  $('dataset').innerHTML = rows.map(r=>`<tr><td>${r.id}</td><td>${format(r['R&D Spend'])}</td><td>${format(r.Administration)}</td><td>${format(r['Marketing Spend'])}</td><td>${r.State}</td><td>${format(r.Profit)}</td><td><span class="${r.split==='test'?'test-badge':''}">${r.split==='test'?'測試':'訓練'}</span></td></tr>`).join('');
}
function render() {
  const model = current();
  $('r2').textContent = format(model.test.R2,4); $('rmse').textContent = format(model.test.RMSE); $('mae').textContent = format(model.test.MAE);
  $('feature-count').textContent = `${selected.length} / 5`;
  $('model-summary').textContent = `${selected.length} 個特徵＋截距 · 訓練集 5-fold CV RMSE ${format(model.cv_rmse)} ± ${format(model.cv_sd)}`;
  DATA.features.forEach((_,i)=>{const label=$(`feature-label-${i}`);label.classList.toggle('active',selected.includes(i));label.querySelector('input').checked=selected.includes(i);});
  $('preset').value = [...$('preset').options].some(o=>o.value===currentKey()) ? currentKey() : 'custom';
  $('coefficients').innerHTML = model.coefficients.map(c=>`<tr><td>${c.name==='const'?'截距':labels[DATA.features.indexOf(c.name)]}<small>${c.name==='const'?'Intercept':c.name}</small></td><td>${format(c.estimate,4)}</td><td>${c.p<.001?'&lt; 0.001':format(c.p,3)}</td><td>[${format(c.lower,3)}, ${format(c.upper,3)}]</td><td>${c.vif===null?'—':format(c.vif)}</td></tr>`).join('');
  $('outliers').innerHTML = model.outliers.map(o=>`<div class="outlier" title="第 ${o.id} 筆；殘差 ${format(o.residual)}">觀測 #${o.id}<strong>${format(o.cook,3)}</strong><i style="width:${Math.max(2,o.cook/model.outliers[0].cook*100)}%"></i></div>`).join('');
  scatterPlot('scatter'); scatterPlot('residuals',true); renderComparison(); predict();
}
function switchTab(name, focus=false) {
  document.querySelectorAll('[role=tab]').forEach(tab=>{const active=tab.dataset.tab===name;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;$(`panel-${tab.dataset.tab}`).hidden=!active;if(active&&focus)tab.focus();});
}
initControls();
document.querySelectorAll('[role=tab]').forEach(tab=>{
  tab.addEventListener('click',()=>switchTab(tab.dataset.tab));
  tab.addEventListener('keydown',e=>{const tabs=[...document.querySelectorAll('[role=tab]')];let index=tabs.indexOf(tab);if(e.key==='ArrowRight')index=(index+1)%tabs.length;else if(e.key==='ArrowLeft')index=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=tabs.length-1;else return;e.preventDefault();switchTab(tabs[index].dataset.tab,true);});
});
$('view-data').addEventListener('click',()=>{switchTab('data',true);$('panel-data').scrollIntoView({behavior:'smooth',block:'start'});});
$('subset-table').addEventListener('click',e=>{const button=e.target.closest('[data-model]');if(button){selected=button.dataset.model.split('-').map(Number);render();toast(`已載入 ${selected.length} 個特徵的模型`);}});
$('data-filter').addEventListener('change',renderData);
$('download-csv').addEventListener('click',()=>{const columns=['R&D Spend','Administration','Marketing Spend','State','Profit'];download('50_Startups.csv',columns.join(',')+'\n'+DATA.rows.map(r=>columns.map(c=>r[c]).join(',')).join('\n'),'text/csv;charset=utf-8');toast('已匯出完整 50 筆資料');});
$('download').addEventListener('click',()=>{
  if(example.some((_,i)=>$(`amount-${i}`).value===''||!$(`amount-${i}`).validity.valid)){toast('請先修正預測輸入數值。');return;}
  download(`startup-model-${currentKey()}.json`,JSON.stringify({seed:42,train_rows:40,test_rows:10,...current(),scenario:prediction(),note:'Holdout metrics use the 40-row training fit; scenario uses the 50-row refit. CV here evaluates fixed feature subsets.'},null,2),'application/json');toast('已匯出模型與情境報告');
});
render();renderData();
